using System;
namespace MET.Core {
/// <summary>Focused pure .NET checks, callable by the migration parity harness.</summary>
public static class FoundationChecks {
 public static V run(string contentRoot){var rows=V.Arr();Action<bool,string> check=(ok,name)=>{rows.Add(V.Map("pass",ok,"name",name));if(!ok)throw new InvalidOperationException(name);};
 var nested=V.Map("inner",V.Map("n",1),"array",V.Arr(1,2));var shallow=nested.Duplicate();var deep=nested.Duplicate(true);shallow["inner"]["n"]=2;check(nested["inner"]["n"].Long==2&&deep["inner"]["n"].Long==1,"shallow shares and deep detaches nested containers");
 var order=V.Map("a",1,"b",2,"c",3);order.Remove("b");order["b"]=4;check(string.Join(",",order.Keys)=="a,c,b","removed and reinserted map key is appended");check(order.Equals(V.Map("b",4,"c",3,"a",1)),"map equality ignores insertion order");check((V.From(7)/V.From(2)).Long==3&&(V.From(7.0)/V.From(2)).Double==3.5,"integer division and double division stay distinct");check(V.Parse("\"2026-10-13T00:00:00Z\"").Text=="2026-10-13T00:00:00Z","JSON strings are not coerced to dates");
 var state=V.Map("rng",V.Map("draft",1));Rng.next(state,"draft");check(state["rng"]["draft"].Long==16807,"Park Miller first state");Rng.next(state,"draft");check(state["rng"]["draft"].Long==282475249,"Park Miller second state");Rng.next(state,"draft");check(state["rng"]["draft"].Long==1622650073,"Park Miller third state uses wide multiply");
 check(Hex.make_map(0).Count==61&&Hex.distance("-4,0","4,0")==8,"full gameplay hex map radius four and distance");check(Hex.connected(V.Arr("0,0","1,0"))&&!Hex.connected(V.Arr("0,0","2,0")),"hex connectivity");
 var stock=V.Map("food|long",3.0,"food|",2.0,"material|",7.0);var taken=Inventory.take(stock,"food",V.Arr("legacy.tag"),4);check(taken["taken"].Double==4&&taken["batches"].Keys[0]=="food|"&&stock["food|long"].Double==1,"inventory dormant tags and shortest-key-first batches");var overlap=V.Map("food|",10.0);var recipe=V.Arr(V.Map("resource","food","rate",10.0,"tags",V.Arr()),V.Map("resource","food","rate",10.0,"tags",V.Arr()));double fraction=Inventory.consume_recipe(overlap,recipe,1);check(Math.Abs(fraction-.5)<.00002&&Inventory.total(overlap,"food")<.0004,"overlapping recipe is atomic with bounded binary search");
 var c=new Catalog(contentRoot);check(c.data["build"].Text=="0.5.0-beta.2"&&c.projects.Has("homestead"),"catalog current content and lineage");check(c.balance["initial_dt"].Double==c.beta["time"]["initial_dt"].Double&&c.balance["offline_dt_per_hour"].Double==0,"beta overrides old economy");check(c.bonus_upgrades.IsMap&&c.commission_themes.IsArray&&c.capstones.IsMap,"bonus themes capstones loaded");
 var encoded=Store.encode(V.Map("rng",V.Map("draft",1),"next_id",2,"elapsed",0.000000643,"text","城"));var decoded=Store.decode(encoded);check(decoded["ok"].Bool&&decoded["state"]["rng"]["draft"].IsInteger&&decoded["state"]["elapsed"].Double==.000000643,"store preserves tiny time and integer cursor");check(Store.encode(decoded["state"])==encoded,"canonical JSON clone round trip");return V.Map("passed",rows.Count,"checks",rows);}
}
}
